"""Agent-facing observation and action parsing helpers."""

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from typing import Any


ACTION_WORDS = ("up", "down", "left", "right")
ACTION_TAG_RE = re.compile(r"<action>\s*(up|down|left|right)\s*</action>", re.IGNORECASE)
ACTION_LINE_RE = re.compile(r"\b(?:action|move|direction)\s*[:=]\s*(up|down|left|right)\b", re.IGNORECASE)
WORD_RE = re.compile(r"\b(up|down|left|right)\b", re.IGNORECASE)


@dataclass(frozen=True)
class ParsedAction:
    action: str
    invalid_parse: bool
    repaired: bool
    error: str | None = None

    def to_dict(self) -> dict[str, Any]:
        return {
            "action": self.action,
            "invalid_parse": self.invalid_parse,
            "repaired": self.repaired,
            "error": self.error,
        }


def parse_action_text(raw_text: str, valid_actions: list[str] | None = None) -> ParsedAction:
    """Parse ReAct/LM output into one Sokoban action.

    The parser is deliberately deterministic. If the text is malformed or names
    an invalid action, it repairs to the first valid action in canonical order.
    """

    valid = [action for action in ACTION_WORDS if not valid_actions or action in valid_actions]
    if not valid:
        return ParsedAction(action="", invalid_parse=True, repaired=False, error="no_valid_actions")

    text = str(raw_text or "").strip()
    candidates: list[str] = []
    for matcher in (ACTION_TAG_RE, ACTION_LINE_RE, WORD_RE):
        match = matcher.search(text)
        if match:
            candidates.append(match.group(1).lower())

    try:
        parsed = json.loads(text)
        if isinstance(parsed, dict):
            value = parsed.get("action", parsed.get("move", parsed.get("direction")))
            if value is not None:
                candidates.insert(0, str(value).lower().strip())
        elif isinstance(parsed, str):
            candidates.insert(0, parsed.lower().strip())
    except json.JSONDecodeError:
        pass

    for candidate in candidates:
        if candidate in valid:
            return ParsedAction(action=candidate, invalid_parse=False, repaired=False)
        if candidate in ACTION_WORDS:
            return ParsedAction(
                action=valid[0],
                invalid_parse=True,
                repaired=True,
                error=f"invalid_action:{candidate}",
            )
    return ParsedAction(action=valid[0], invalid_parse=True, repaired=True, error="no_action_found")


def format_agent_observation(readout: dict[str, Any], *, objective: str | None = None) -> dict[str, Any]:
    public = readout["public"]
    private = readout["private"]
    valid_actions = list(readout.get("valid_actions", []))
    remaining = max(0, int(private.get("max_steps", 0) or 0) - int(private.get("step_index", 0)))
    lines = [
        objective or "Push every box onto a target.",
        "",
        "Legend: # wall, @ player, $ box, . target, * box on target, + player on target.",
        "Board:",
        str(readout.get("ascii", "")),
        "",
        f"Valid actions: {', '.join(valid_actions) if valid_actions else 'none'}",
        f"Boxes on target: {public.get('boxes_on_target', 0)}",
        f"Reward total: {private.get('total_reward', 0.0):.2f}",
        f"Step: {private.get('step_index', 0)}",
    ]
    if remaining:
        lines.append(f"Steps remaining: {remaining}")
    lines.append('Reply with exactly one move as JSON, for example {"action":"right"}.')
    return {
        "observation_text": "\n".join(lines),
        "ascii": readout.get("ascii", ""),
        "valid_actions": valid_actions,
        "grid_hash": readout.get("grid_hash"),
        "public": public,
        "private": private,
    }

"""Small HTTP client for Sokoban gold services."""

from __future__ import annotations

import base64
from dataclasses import dataclass
from typing import Any

import httpx


@dataclass
class SokobanGoldClient:
    base_url: str
    timeout: float = 60.0

    def health(self) -> dict[str, Any]:
        return self._get("/health")

    def create_rollout(self, task: dict[str, Any], *, seed: int | None = None) -> dict[str, Any]:
        body: dict[str, Any] = {"task": task}
        if seed is not None:
            body["seed"] = seed
        return self._post("/rollouts", body)

    def step(self, rollout_id: str, action: str) -> dict[str, Any]:
        return self._post(f"/rollouts/{rollout_id}/step", {"action": action})

    def checkpoint(self, rollout_id: str) -> dict[str, Any]:
        return self._post(f"/rollouts/{rollout_id}/checkpoint", {})

    def restore(self, rollout_id: str, blob: bytes) -> dict[str, Any]:
        return self._post(f"/rollouts/{rollout_id}/restore", {"blob": base64.b64encode(blob).decode("ascii")})

    def simulate(self, rollout_id: str, blob: bytes, sequences: list[list[str]]) -> dict[str, Any]:
        return self._post(
            f"/rollouts/{rollout_id}/simulate",
            {"blob": base64.b64encode(blob).decode("ascii"), "sequences": sequences},
        )

    def readout(self, rollout_id: str) -> dict[str, Any]:
        return self._get(f"/rollouts/{rollout_id}/readout")

    def event_log(self, rollout_id: str) -> dict[str, Any]:
        return self._get(f"/rollouts/{rollout_id}/event_log")

    def _get(self, path: str) -> dict[str, Any]:
        with httpx.Client(timeout=self.timeout) as client:
            response = client.get(f"{self.base_url.rstrip('/')}{path}")
            response.raise_for_status()
            return response.json()

    def _post(self, path: str, body: dict[str, Any]) -> dict[str, Any]:
        with httpx.Client(timeout=self.timeout) as client:
            response = client.post(f"{self.base_url.rstrip('/')}{path}", json=body)
            response.raise_for_status()
            return response.json()

"""Shaped reward for pushes vs idle steps."""

from __future__ import annotations

from typing import Any


def score_transition(
    *,
    spec: dict[str, Any],
    event: str,
    pushed: bool = False,
    **_: Any,
) -> float:
    if event == "level_complete":
        return 0.0
    if pushed:
        return float(spec.get("push_bonus", 0.02))
    return float(spec.get("idle_penalty", -0.005))

"""Sokoban observations and symbolic readouts."""

from __future__ import annotations

import hashlib
from typing import Any

from task_resolve import grid_to_ascii


ACTIONS = ["up", "down", "left", "right"]


def ascii_board(room_fixed: list[list[int]], player: tuple[int, int], boxes: set[tuple[int, int]]) -> str:
    return "\n".join(grid_to_ascii(room_fixed, player, boxes))


def grid_hash(room_state: list[list[int]]) -> str:
    payload = "|".join(",".join(str(cell) for cell in row) for row in room_state)
    return hashlib.sha256(payload.encode()).hexdigest()[:16]


def project_readout(engine: Any) -> dict[str, Any]:
    private = engine.private.to_dict()
    if engine.resolved is not None:
        private["max_steps"] = engine.resolved.max_steps
    return {
        "ascii": ascii_board(engine.room_fixed, engine.player, engine.boxes),
        "valid_actions": engine.valid_actions(),
        "grid_hash": grid_hash(engine.room_state),
        "public": engine.public.to_dict(),
        "private": private,
    }

"""Render helpers for Sokoban v0."""

from __future__ import annotations

import struct
import zlib

from observations import ascii_board


COLORS = {
    "#": (45, 48, 54),
    " ": (238, 238, 232),
    ".": (246, 214, 92),
    "$": (171, 111, 62),
    "*": (80, 170, 105),
    "@": (80, 140, 220),
    "+": (80, 170, 220),
}


def render_ascii(engine: object) -> str:
    return ascii_board(engine.room_fixed, engine.player, engine.boxes)


def render_svg(engine: object, *, tile_size: int = 32) -> str:
    rows = render_ascii(engine).splitlines()
    width = max(len(row) for row in rows) if rows else 0
    height = len(rows)
    parts = [
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width * tile_size}" height="{height * tile_size}" viewBox="0 0 {width * tile_size} {height * tile_size}">'
    ]
    for r, row in enumerate(rows):
        for c, ch in enumerate(row.ljust(width)):
            color = COLORS.get(ch, COLORS[" "])
            parts.append(
                f'<rect x="{c * tile_size}" y="{r * tile_size}" width="{tile_size}" height="{tile_size}" fill="rgb({color[0]},{color[1]},{color[2]})"/>'
            )
            if ch in "$*@+":
                label = "P" if ch in "@+" else "B"
                parts.append(
                    f'<text x="{c * tile_size + tile_size / 2}" y="{r * tile_size + tile_size * 0.66}" text-anchor="middle" font-size="{tile_size * 0.5}" font-family="monospace" fill="white">{label}</text>'
                )
    parts.append("</svg>")
    return "".join(parts)


def render_png_bytes(engine: object, *, tile_size: int = 24) -> bytes:
    rows = render_ascii(engine).splitlines()
    width_tiles = max(len(row) for row in rows) if rows else 1
    height_tiles = max(len(rows), 1)
    width = width_tiles * tile_size
    height = height_tiles * tile_size
    raw = bytearray()
    for y in range(height):
        raw.append(0)
        tile_r = y // tile_size
        row = rows[tile_r].ljust(width_tiles) if tile_r < len(rows) else " " * width_tiles
        for x in range(width):
            ch = row[x // tile_size]
            raw.extend(COLORS.get(ch, COLORS[" "]))
    return _png(width, height, bytes(raw))


def _png(width: int, height: int, raw_scanlines: bytes) -> bytes:
    def chunk(kind: bytes, data: bytes) -> bytes:
        crc = zlib.crc32(kind + data) & 0xFFFFFFFF
        return struct.pack(">I", len(data)) + kind + data + struct.pack(">I", crc)

    return b"\x89PNG\r\n\x1a\n" + chunk(
        b"IHDR",
        struct.pack(">IIBBBBB", width, height, 8, 2, 0, 0, 0),
    ) + chunk(b"IDAT", zlib.compress(raw_scanlines)) + chunk(b"IEND", b"")

"""Golden scenario runner for Sokoban."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from engine import SokobanEngine
from task_resolve import resolve_task


TASK_DIR = Path(__file__).resolve().parents[1]


def load_json(path: Path) -> dict[str, Any]:
    return json.loads(path.read_text())


def scenario_to_task(entry: dict[str, Any]) -> dict[str, Any]:
    if "task" in entry:
        return dict(entry["task"])
    return {
        "schema": "gamebench.task.sokoban.v1",
        "task_id": entry["scenario_id"],
        "seed": int(entry.get("seed", 0)),
        "map": dict(entry["map"]),
        "rules": dict(entry.get("rules", {"base": "sparse_sokoban"})),
        "readouts": {"symbolic": "ascii_annotated", "visual": False},
        "checkpoint_every_n_steps": 1,
    }


def run_scenario(entry_or_task: dict[str, Any]) -> dict[str, Any]:
    if "scenario_id" in entry_or_task:
        scenario_id = str(entry_or_task["scenario_id"])
        task = scenario_to_task(entry_or_task)
        actions = list(entry_or_task.get("actions", []))
    else:
        task = dict(entry_or_task)
        scenario_id = str(task.get("task_id", "manual"))
        actions = list(task.get("actions", []))

    engine = SokobanEngine()
    engine.reset(resolve_task(task))
    for action in actions:
        if engine.private.terminated or engine.private.truncated:
            break
        engine.step(str(action))

    return {
        "scenario_id": scenario_id,
        "events": engine.nev.legacy_strings(),
        "nev": engine.nev.export(),
        "state": {
            "public": engine.public.to_dict(),
            "private": engine.private.to_dict(),
        },
        "readout": engine.symbolic_readout(),
    }

"""FastAPI service for the Python Sokoban gold lane."""

from __future__ import annotations

import base64
import uuid
from dataclasses import dataclass, field
from typing import Any

from fastapi import FastAPI, HTTPException
from fastapi.responses import Response
from pydantic import BaseModel

from core.checkpoint import RestoreReport
from engine import SokobanEngine
from render import render_png_bytes, render_svg
from scenarios import run_scenario
from task_resolve import resolve_task


class ScenarioRequest(BaseModel):
    task: dict[str, Any]


class RolloutRequest(BaseModel):
    task: dict[str, Any] | None = None
    seed: int | None = None


class StepRequest(BaseModel):
    action: str


class RestoreRequest(BaseModel):
    blob: str


class SimulateRequest(BaseModel):
    blob: str
    sequences: list[list[str]]


@dataclass
class RolloutSession:
    rollout_id: str
    engine: SokobanEngine
    checkpoints: dict[str, bytes] = field(default_factory=dict)


def create_app() -> FastAPI:
    app = FastAPI(title="GameBench Sokoban Python Gold", version="0.1.0")
    sessions: dict[str, RolloutSession] = {}

    @app.get("/health")
    def health() -> dict[str, Any]:
        return {"ok": True, "lane": "python", "env_family": SokobanEngine.ENV_FAMILY, "sessions": len(sessions)}

    @app.post("/run_scenario")
    def run_scenario_route(body: ScenarioRequest) -> dict[str, Any]:
        return run_scenario(body.task)

    @app.post("/rollouts")
    def create_rollout(body: RolloutRequest) -> dict[str, Any]:
        task = body.task or {
            "schema": "gamebench.task.sokoban.v1",
            "task_id": "manual",
            "map": {"source": "inline", "grid": ["#####", "#@$.#", "#####"]},
            "rules": {"base": "sparse_sokoban"},
        }
        engine = SokobanEngine()
        engine.reset(resolve_task(task, seed_override=body.seed))
        rollout_id = str(uuid.uuid4())
        sessions[rollout_id] = RolloutSession(rollout_id, engine)
        return _payload(sessions[rollout_id])

    @app.post("/rollouts/{rollout_id}/step")
    def step(rollout_id: str, body: StepRequest) -> dict[str, Any]:
        session = _require(sessions, rollout_id)
        session.engine.step(body.action)
        return _payload(session)

    @app.post("/rollouts/{rollout_id}/checkpoint")
    def checkpoint(rollout_id: str) -> dict[str, Any]:
        session = _require(sessions, rollout_id)
        blob = session.engine.checkpoint_bytes()
        checkpoint_id = str(uuid.uuid4())
        session.checkpoints[checkpoint_id] = blob
        return {
            "rollout_id": rollout_id,
            "checkpoint_id": checkpoint_id,
            "blob": base64.b64encode(blob).decode("ascii"),
            "bytes": len(blob),
            "nev_cursor": session.engine.nev.cursor(),
        }

    @app.post("/rollouts/{rollout_id}/restore")
    def restore(rollout_id: str, body: RestoreRequest) -> dict[str, Any]:
        session = _require(sessions, rollout_id)
        blob = base64.b64decode(body.blob.encode("ascii"))
        restored = session.engine.restore_checkpoint(blob)
        return {
            "rollout_id": rollout_id,
            "restore_report": RestoreReport(bytes=len(blob), wall_ms=0.0, nev_events_restored=restored).to_dict(),
            "readout": session.engine.symbolic_readout(),
        }

    @app.post("/rollouts/{rollout_id}/simulate")
    def simulate(rollout_id: str, body: SimulateRequest) -> dict[str, Any]:
        session = _require(sessions, rollout_id)
        root_blob = base64.b64decode(body.blob.encode("ascii"))
        results: list[dict[str, Any]] = []
        for index, sequence in enumerate(body.sequences):
            sim = session.engine.clone_for_sim()
            sim.restore_checkpoint(root_blob)
            for action in sequence:
                if sim.private.terminated or sim.private.truncated:
                    break
                sim.step(action)
            results.append(
                {
                    "index": index,
                    "actions": sequence,
                    "reward": sim.private.total_reward,
                    "terminated": sim.private.terminated,
                    "truncated": sim.private.truncated,
                    "readout": sim.symbolic_readout(),
                    "nev_cursor": sim.nev.cursor(),
                }
            )
        return {
            "rollout_id": rollout_id,
            "root_nev_cursor": session.engine.nev.cursor(),
            "results": results,
        }

    @app.get("/rollouts/{rollout_id}/readout")
    def readout(rollout_id: str) -> dict[str, Any]:
        return _require(sessions, rollout_id).engine.symbolic_readout()

    @app.get("/rollouts/{rollout_id}/event_log")
    def event_log(rollout_id: str) -> dict[str, Any]:
        engine = _require(sessions, rollout_id).engine
        return {"events": engine.nev.export(), "legacy": engine.nev.legacy_strings(), "nev_cursor": engine.nev.cursor()}

    @app.get("/rollouts/{rollout_id}/render.svg")
    def render_svg_route(rollout_id: str) -> Response:
        engine = _require(sessions, rollout_id).engine
        return Response(content=render_svg(engine), media_type="image/svg+xml")

    @app.get("/rollouts/{rollout_id}/render.png")
    def render_png_route(rollout_id: str) -> Response:
        engine = _require(sessions, rollout_id).engine
        return Response(content=render_png_bytes(engine), media_type="image/png")

    return app


def _require(sessions: dict[str, RolloutSession], rollout_id: str) -> RolloutSession:
    session = sessions.get(rollout_id)
    if session is None:
        raise HTTPException(status_code=404, detail="rollout not found")
    return session


def _payload(session: RolloutSession) -> dict[str, Any]:
    engine = session.engine
    return {
        "rollout_id": session.rollout_id,
        "readout": engine.symbolic_readout(),
        "reward": engine.private.total_reward,
        "terminated": engine.private.terminated,
        "truncated": engine.private.truncated,
        "nev_cursor": engine.nev.cursor(),
    }


app = create_app()

"""Public/private state split for Sokoban."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any


@dataclass
class PublicState:
    room_state: list[list[int]]
    player: tuple[int, int]
    boxes: list[tuple[int, int]]
    boxes_on_target: int
    done: bool = False

    def to_dict(self) -> dict[str, Any]:
        return {
            "room_state": self.room_state,
            "player": list(self.player),
            "boxes": [list(pos) for pos in self.boxes],
            "boxes_on_target": self.boxes_on_target,
            "done": self.done,
        }

    def diff(self, other: "PublicState") -> dict[str, Any]:
        changes: dict[str, Any] = {}
        if self.room_state != other.room_state:
            changes["room_state"] = {"from": other.room_state, "to": self.room_state}
        if self.player != other.player:
            changes["player"] = {"from": list(other.player), "to": list(self.player)}
        if self.boxes != other.boxes:
            changes["boxes"] = {"from": [list(p) for p in other.boxes], "to": [list(p) for p in self.boxes]}
        if self.boxes_on_target != other.boxes_on_target:
            changes["boxes_on_target"] = {"from": other.boxes_on_target, "to": self.boxes_on_target}
        if self.done != other.done:
            changes["done"] = {"from": other.done, "to": self.done}
        return changes


@dataclass
class PrivateState:
    episode_id: str
    task_id: str
    puzzle_id: str
    seed: int
    config_hash: str
    step_index: int = 0
    reward_last: float = 0.0
    total_reward: float = 0.0
    terminated: bool = False
    truncated: bool = False
    achievements: set[str] = field(default_factory=set)

    def to_dict(self) -> dict[str, Any]:
        return {
            "episode_id": self.episode_id,
            "task_id": self.task_id,
            "puzzle_id": self.puzzle_id,
            "seed": self.seed,
            "config_hash": self.config_hash,
            "step_index": self.step_index,
            "reward_last": self.reward_last,
            "total_reward": self.total_reward,
            "terminated": self.terminated,
            "truncated": self.truncated,
            "achievements": sorted(self.achievements),
        }


@dataclass
class SimSnapshot:
    public: PublicState
    private: PrivateState
    nev_events: list[dict[str, Any]] = field(default_factory=list)

