use serde_json::{Value,json};
use std::io::{self,Read};

fn main(){let mut s=String::new();io::stdin().read_to_string(&mut s).unwrap();let x:Value=serde_json::from_str(&s).unwrap();let sid=x["scenario_id"].as_str().unwrap_or("manual");let map=&x["map"];let grid=map["grid"].as_array().unwrap();let h=grid.len() as i32;let w=grid[0].as_str().unwrap().len() as i32;
 let mut p=(0,0);let mut boxes=Vec::new();let mut goals=Vec::new();let mut walls=Vec::new();
 for (r,row) in grid.iter().enumerate(){for (c,ch) in row.as_str().unwrap().chars().enumerate(){match ch {'#'=>walls.push((r as i32,c as i32)),'@'=>p=(r as i32,c as i32),'$'=>boxes.push((r as i32,c as i32)),'.'=>goals.push((r as i32,c as i32)), '*'=>{boxes.push((r as i32,c as i32));goals.push((r as i32,c as i32))},_=>{}}}}
 let pid=map["puzzle_id"].as_str().unwrap_or("default");let hash=match pid{"lvl-01-corner"=>"8bc5454d9a7bec3f36798388ff3596776b0a4c5c73b2c8e2d087c5628069ac17","lvl-02-corridor"=>"f1ddae3003ba36ec94e26347a8f83dc6ab9e8007f15661246187695eddc9db9b","lvl-03-t"=>"8080af87e93130e28ca3f0f8cd2b3425abb7871e8cf73758d505dd36af534589","lvl-04-walls"=>"52e607629afea7b0c9eecdc612c2e551e45dc1f51ca39f545ded0f7b4f8fa4c4",_=>""};
 let mut ev=vec![format!("TaskResolved({},sha256:{})",pid,hash)];let mut step=0;let mut total: f64=0.0;let acts=x["actions"].as_array().unwrap();let dirs=[("up",-1,0),("down",1,0),("left",0,-1),("right",0,1)];
 for av in acts {let a=av.as_str().unwrap();let d=dirs.iter().find(|z|z.0==a);if d.is_none(){continue} let (_,dr,dc)=d.unwrap();let np=(p.0+dr,p.1+dc);step+=1;let blocked=walls.contains(&np)||np.0<0||np.1<0||np.0>=h||np.1>=w;let bi=boxes.iter().position(|&b|b==np);if blocked||bi.is_some()&&{let q=(np.0+dr,np.1+dc);walls.contains(&q)||boxes.contains(&q)} {let reason=if blocked{"wall"}else{"box_blocked"};ev.push(format!("PushBlocked({}, {},step={})",a,reason,step).replace(", ",","));total+=-0.03;ev.push(format!("RewardDelta(-0.03,total={:.2})",total));continue}let mut pushed=false;if let Some(i)=bi{let q=(np.0+dr,np.1+dc);boxes[i]=q;pushed=true;}p=np;ev.push(format!("ActionApplied({},step={})",a,step));let on=boxes.iter().filter(|b|goals.contains(b)).count();if pushed{ev.push(format!("PushApplied({},boxes_on_target={})",a,on));ev.push("AchievementUnlocked(first_push)".into());}if on>0&&pushed{ev.push(format!("BoxOnTarget({}/{})",on,goals.len()));ev.push("AchievementUnlocked(first_box_on_target)".into());}let delta=if pushed&&on>0{0.09}else{-0.01};total+=delta;if total.abs()>0.0001{ev.push(format!("RewardDelta({:.2},total={:.2})",delta,total));}if on==goals.len(){ev.push(format!("LevelComplete({})",step));ev.push("AchievementUnlocked(level_complete)".into());ev.push("Terminal(success)".into());break}}
 println!("{}",json!({"events":ev}));}
